def predict(x):
    if x[0] <= 5:
        if x[1] <= 2:
            return 1
        return 0
    if x[1] <= 4:
        return 0
    return 1

pred_a = predict((4, 3))
pred_b = predict((6, 3))
pred_c = predict((6, 5))
votes = pred_a + pred_b + pred_c
pred = 1 if votes >= 2 else 0

vocab = {"<pad>": 0, "</w>": 1, "a": 2, "b": 3, "c": 4}

def encode(s):
    return [vocab["<pad>"]] + [vocab[ch] for ch in s] + [vocab["</w>"]]

ids = encode("cab")
print(ids)
print(len(set(ids)) == len(ids))

def freeze(names):
    return {n: (False if n.startswith("backbone") else True) for n in names}

params = freeze(["backbone.w1", "backbone.w2", "head.w3"])
print(sum(1 for trainable in params.values() if trainable))
print(sorted(n for n, t in params.items() if not t)[0])
